     * format with a 4-digit year.
     * This is the time the usage occurred, or the end of the usage period.
     * <br><br>
     * Example: `"2023-02-08T19:24:10Z"`
     *
     **/
    @IsRFC3339()
    @IsString()
    @IsNotEmpty()
    public timeStamp: string;

    /**
     * Conditionally REQUIRED.<br>
     * The application ID of a service this usage record attributes to.
     * This field is required if the `serviceId` is not provided.
     * If both are provided the `serviceId` takes precedence
     * and both  persist in usage records.
     * <br><br>
     * Example: `"e8366954-6f36-47e9-8431-ac95f88b5cc7"`
     *
     **/
    @IsString()
    @IsOptional()
    @IsAscii()
    public applicationId?: string;

    /**
     * Conditionally REQUIRED.<br>
     * The service ID of a service this usage record attributes to.
     * This field is required if the `applicationId` is not provided.
     * If both are provided the `serviceId` takes precedence
     * and both persist in usage records.
     * <br><br>
     * Example: `'e8366954-6f36-47e9-8431-ac95f88b5cc7'`
     *
     **/
    @ValidServiceApplicationID('serviceId', {
        message: 'Must provide either a serviceId or a applicationId',
    })
    @ServiceIdExists('serviceId')
    public serviceId?: string;

    /**
     * The unique identifier of the dimension this usage record is associated with.
     * <br><br>
     * Example: `'da9611bd-e0f3-4c0d-a754-fda5be730872'`
     *
     **/
    @IsString()
    @IsNotEmpty()
    @DimensionIdExists('dimensionId')
    public dimensionId?: string;

    /**
     * The amount of the usage on this record.
     * Numerical values are represented as strings to avoid precision loss.
     * <br><br>
     * Example: `"0.87"`
     **/
    @IsNumberString()
    @IsString()
    public recordValue: number;

    /**
     * An optional key-value map of additional metadata to associate with this usage record.
     * Additional metadata to be stored on the usage record,
     * such as environment, purpose, owner, developer, contract number,
     * or any arbitrary data to be associated with this usage record.
     * Metadata can be used for analytics purpose.
     * <br><br>
     * Example `{"environment": "staging", "purpose": "proof-of-concept", "owner": "John Doe"}`
     **/
    @IsObject()
    @IsOptional()
    public metadata: Record<string, string>;
}
import { Point } from '@influxdata/influxdb-client';
import { MeasurementInfluxDbModel } from '../../influx/entities/measurementInfluxDbModel.interface';
import { InfluxService } from '../../influx/influx.service';
export enum ValidMeasurementTypes {
    int = 'int',
    float = 'float',
}

export abstract class MeasurementFormat {
    dimensionId?: string;
    applicationId?: string;
    serviceId?: string;
    timeStamp?: string;
    recordValue: number;
    businessID: string;
    metadata: Record<string, string>;
    _measurement: string;
    static getPointForm(measurement: MeasurementFormat, influxService: InfluxService): Point {
        const point = influxService.getPoint(measurement._measurement);
        point.timestamp(new Date(measurement.timeStamp));
        point.tag('applicationId', measurement.applicationId);
        point.tag('dimensionId', measurement.dimensionId);
        point.tag('serviceId', measurement.serviceId);
        point.tag('businessID', measurement.businessID);
        point.floatField('recordValue', measurement.recordValue);
        if (measurement?.metadata) {
            Object.keys(measurement.metadata).forEach((key) => {
                point.tag(`metadata_${key}`, measurement.metadata[key]);
            });
        }
        return point;
    }
    static toEntity(dbModel: MeasurementInfluxDbModel): MeasurementFormat {
        const measurementInput: MeasurementFormat = {
            timeStamp: dbModel._time,
            dimensionId: dbModel.dimensionId,
            applicationId: dbModel.applicationId,
            recordValue: dbModel._value,
            metadata: {},
            _measurement: dbModel._measurement,
            businessID: dbModel.businessID,
        };
        Object.keys(dbModel).forEach((key) => {
            if (key.startsWith('metadata_') && dbModel[key]) {
                // eslint-disable-next-line @typescript-eslint/ban-ts-comment
                // @ts-ignore
                measurementInput.metadata[key.replace('metadata_', '')] = dbModel[key];
            }
        });
        return measurementInput;
    }
}

