export enum SupportedDatastores {
    s3 = 's3',
}

/**
 * The region used for datastore based measurements when a region is not provided.
 */
export const DEFAULT_DATASTORE_REGION = 'us-east-1';

/**
 * Optional context which carries the identifiers needed to name and scope the
 * resources provisioned for a datastore based measurement.
 */
export interface DatastoreAccessContext {
    businessID?: string;
    measurementId?: string;
}

/**
 *
 * This Class represents the access information and control data structure for Datastore based Measurement solutions
 * Specifically this is the access information needed for the connectors which ingest usage data from a clients datastore.
 * There are many different connectors with different access and control needs.
 * For example a MySQL connector is not the same as an S3 Connector.
 *
 * For `s3` based measurements Paigo provisions a dedicated IAM role, scoped to the ingestion and dead letter
 * queue prefixes of the business, which the customer account is allowed to assume with the generated external ID.
 * */
export class DatastoreAccessInformation {
    /**
     * The datastore platform which Paigo ingests usage data from. Optional, default is `s3`.
     *
     */
    @Matches(
        `^${Object.values(SupportedDatastores)
            .filter((v) => typeof v !== 'number')
            .join('|')}$`,
        'i'
    )
    @IsOptional()
    @ApiProperty({
        enum: SupportedDatastores,
        isArray: false,
        required: false,
        example: 's3',
    })
    public platform?: SupportedDatastores;

    /**
     * The unique ID of the cloud account which owns the data being ingested. Required.
     * This is the account which is trusted to assume the generated IAM role.
     * @example "623673123435"
     */
    @IsString()
    @IsNotEmpty()
    @ApiProperty({ example: '623673123435' })
    public accountId: string;

    /**
     * The region the ingestion location lives in. Optional, default is `us-east-1`.
     * @example "us-east-1"
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, example: DEFAULT_DATASTORE_REGION })
    public region?: string;

    /**
     * The IAM role, generated by Paigo, which the customer account assumes to deliver usage data.
     * <br><br>
     * Example "arn:aws:iam::214826386939:role/datastore-myBusiness-de388932-a7e1-11ed-afa1-0242ac120002"
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public iamRoleArn?: string;

    /**
     * The external ID, generated by Paigo, which must be used when assuming the generated IAM role.
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public externalId?: string;

    /**
     * The location usage data is delivered to.
     * <br><br>
     * Example "s3://paigo-usage-record-dump-bucket/myBusiness"
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public ingestion?: string;

    /**
     * The location failed usage records are delivered to.
     * <br><br>
     * Example "s3://paigo-usage-record-dlq-bucket/myBusiness"
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public dlq?: string;

    @ApiHideProperty()
    @IsOptional()
    public businessID?: string;

    @ApiHideProperty()
    @IsOptional()
    public measurementId?: string;

    constructor(datastoreAccessInformation: DatastoreAccessInformation & { [x: string]: any }) {
        if (datastoreAccessInformation) {
            const {
                platform,
                accountId,
                region,
                iamRoleArn,
                externalId,
                ingestion,
                dlq,
                businessID,
                measurementId,
                // Legacy names, kept so previously stored configurations keep resolving
                datastoreType,
                cloudId,
            } = datastoreAccessInformation;

            this.platform = DatastoreAccessInformation.resolvePlatform({ platform, datastoreType });
            this.accountId = accountId ? accountId : cloudId;
            this.region = region ? region : DEFAULT_DATASTORE_REGION;
            if (iamRoleArn) {
                this.iamRoleArn = iamRoleArn;
            }
            if (externalId) {
                this.externalId = externalId;
            }
            if (ingestion) {
                this.ingestion = ingestion;
            }
            if (dlq) {
                this.dlq = dlq;
            }
            if (businessID) {
                this.businessID = businessID;
            }
            if (measurementId) {
                this.measurementId = measurementId;
            }
        }
    }

    public static transformer(datastoreAccessInformation: DatastoreAccessInformation, influxPoint: Point) {
        if (datastoreAccessInformation) {
            const { platform, accountId, region, iamRoleArn, externalId, ingestion, dlq } =
                datastoreAccessInformation;
            if (platform) influxPoint.tag('platform', platform.toLowerCase());
            if (accountId) influxPoint.tag('accountId', accountId);
            if (region) influxPoint.tag('region', region);
            if (iamRoleArn) influxPoint.tag('iamRoleArn', iamRoleArn);
            if (externalId) influxPoint.tag('externalId', externalId);
            if (ingestion) influxPoint.tag('ingestion', ingestion);
            if (dlq) influxPoint.tag('dlq', dlq);
        }
        return influxPoint;
    }

    public static dbModelToEntity({
        platform,
        datastoreType,
        accountId,
        cloudId,
        region,
        iamRoleArn,
        externalId,
        ingestion,
        dlq,
        businessID,
        measurementId,
    }: {
        [x: string]: any;
    }) {
        return new DatastoreAccessInformation({
            platform,
            datastoreType,
            accountId,
            cloudId,
            region,
            iamRoleArn,
            externalId,
            ingestion,
            dlq,
            businessID,
            measurementId,
        } as DatastoreAccessInformation);
    }

    /**
     * Provisions everything a customer needs to deliver usage data into Paigo.
     *
     * For `s3` platforms a uniquely named IAM role, scoped to the ingestion and dead letter queue
     * prefixes of the business, is created. The customer account is trusted to assume the role
     * with a freshly generated external ID.
     *
     * @returns the access information enriched with the generated access details.
     */
    public static async setupAccess(
        dbAccessInformation: DatastoreAccessInformation,
        context: DatastoreAccessContext = {}
    ): Promise<DatastoreAccessInformation> {
        const resolved = DatastoreAccessInformation.resolveDetails(dbAccessInformation, context);
        const { platform, accountId, businessID, measurementId, region, ingestion, dlq } = resolved;

        if (platform !== SupportedDatastores.s3) {
            return DatastoreAccessInformation.enrich(dbAccessInformation, resolved);
        }

        const roleName = DatastoreAccessInformation.roleName({ businessID, measurementId });
        const externalId = resolved.externalId ? resolved.externalId : randomUUID();
        const trustPolicy = DatastoreAccessInformation.buildTrustPolicy({ accountId, externalId });
        const accessPolicy = DatastoreAccessInformation.buildAccessPolicy({ businessID });

        let iamRoleArn = resolved.iamRoleArn;
        try {
            const iam = DatastoreAccessInformation.getIamClient(region);
            const createdRole = await iam.send(
                new CreateRoleCommand({
                    RoleName: roleName,
                    AssumeRolePolicyDocument: JSON.stringify(trustPolicy),
                })
            );
            iamRoleArn = createdRole?.Role?.Arn
                ? createdRole.Role.Arn
                : DatastoreAccessInformation.buildRoleArn(roleName);

            await iam.send(
                new PutRolePolicyCommand({
                    RoleName: roleName,
                    PolicyName: roleName,
                    PolicyDocument: JSON.stringify(accessPolicy),
                })
            );

            try {
                const createdPolicy = await iam.send(
                    new CreatePolicyCommand({
                        PolicyName: roleName,
                        PolicyDocument: JSON.stringify(accessPolicy),
                    })
                );
                const policyArn = createdPolicy?.Policy?.Arn;
                if (policyArn) {
                    await iam.send(new AttachRolePolicyCommand({ RoleName: roleName, PolicyArn: policyArn }));
                }
            } catch (policyError) {
                // The role already carries the inline policy, a managed policy is a convenience only
                MeasurementConfigLogger.warn(
                    `Unable to create managed policy ${roleName}: ${policyError?.message ?? policyError}`
                );
            }
        } catch (e) {
            throw DatastoreAccessInformation.translateError(e, accountId);
        }

        return DatastoreAccessInformation.enrich(dbAccessInformation, {
            ...resolved,
            platform,
            region,
            ingestion,
            dlq,
            iamRoleArn,
            externalId,
        });
    }

    /**
     * Updates the trust relationship of an already provisioned IAM role so that a new customer
     * account can assume it. The generated role and external ID are preserved.
     *
     * @returns the access information with the preserved access details.
     */
    public static async updateAccess(
        dbAccessInformation: DatastoreAccessInformation,
        context: DatastoreAccessContext = {}
    ): Promise<DatastoreAccessInformation> {
        const resolved = DatastoreAccessInformation.resolveDetails(dbAccessInformation, context);
        const { platform, accountId, businessID, measurementId, region, ingestion, dlq } = resolved;

        if (platform !== SupportedDatastores.s3) {
            return DatastoreAccessInformation.enrich(dbAccessInformation, resolved);
        }

        const iamRoleArn = resolved.iamRoleArn;
        const roleName = DatastoreAccessInformation.roleNameFromArn(iamRoleArn)
            ? DatastoreAccessInformation.roleNameFromArn(iamRoleArn)
            : DatastoreAccessInformation.roleName({ businessID, measurementId });
        const externalId = resolved.externalId ? resolved.externalId : randomUUID();
        const trustPolicy = DatastoreAccessInformation.buildTrustPolicy({ accountId, externalId });

        try {
            const iam = DatastoreAccessInformation.getIamClient(region);
            await iam.send(
                new UpdateAssumeRolePolicyCommand({
                    RoleName: roleName,
                    PolicyDocument: JSON.stringify(trustPolicy),
                })
            );
        } catch (e) {
            throw DatastoreAccessInformation.translateError(e, accountId);
        }

        return DatastoreAccessInformation.enrich(dbAccessInformation, {
            ...resolved,
            platform,
            region,
            ingestion,
            dlq,
            externalId,
            iamRoleArn: iamRoleArn ? iamRoleArn : DatastoreAccessInformation.buildRoleArn(roleName),
        });
    }

    /**
     * The unique name given to the IAM role, and policy, provisioned for a measurement.
     */
    public static roleName({ businessID, measurementId }: DatastoreAccessContext): string {
        return `datastore-${businessID}-${measurementId}`;
    }

    /**
     * The location, in the ingestion datastore, usage data for a business is delivered to.
     */
    public static ingestionLocation(businessID: string): string {
        return `s3://${process.env.DB_MEASUREMENT_BUCKET_NAME}/${businessID}`;
    }

    /**
     * The location, in the dead letter queue datastore, failed usage records for a business are delivered to.
     */
    public static dlqLocation(businessID: string): string {
        return `s3://${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${businessID}`;
    }

    public static buildTrustPolicy({ accountId, externalId }: { accountId: string; externalId: string }) {
        return {
            Version: '2012-10-17',
            Statement: [
                {
                    Sid: 'AllowCustomerAccountToAssumeRole',
                    Effect: 'Allow',
                    Principal: {
                        AWS: `arn:aws:iam::${accountId}:root`,
                    },
                    Action: 'sts:AssumeRole',
                    Condition: {
                        StringEquals: {
                            'sts:ExternalId': externalId,
                        },
                    },
                },
            ],
        };
    }

    public static buildAccessPolicy({ businessID }: { businessID: string }) {
        return {
            Version: '2012-10-17',
            Statement: [
                {
                    Sid: 'UsageDataIngestion',
                    Effect: 'Allow',
                    Action: ['s3:PutObject', 's3:GetObject', 's3:AbortMultipartUpload', 's3:ListMultipartUploadParts'],
                    Resource: [`arn:aws:s3:::${process.env.DB_MEASUREMENT_BUCKET_NAME}/${businessID}/*`],
                },
                {
                    Sid: 'UsageDataDeadLetterQueue',
                    Effect: 'Allow',
                    Action: ['s3:GetObject', 's3:PutObject'],
                    Resource: [`arn:aws:s3:::${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${businessID}/*`],
                },
            ],
        };
    }

    private static getIamClient(region?: string) {
        return new IAM({ region: process.env.AWS_REGION ? process.env.AWS_REGION : region ?? DEFAULT_DATASTORE_REGION });
    }

    private static resolvePlatform({ platform, datastoreType }: { [x: string]: any }): SupportedDatastores {
        const chosen = platform ? platform : datastoreType;
        return (chosen ? String(chosen).toLowerCase() : SupportedDatastores.s3) as SupportedDatastores;
    }

    private static resolveDetails(
        dbAccessInformation: DatastoreAccessInformation & { [x: string]: any },
        context: DatastoreAccessContext = {}
    ) {
        const information = dbAccessInformation ? dbAccessInformation : ({} as DatastoreAccessInformation);
        const businessID = context?.businessID ? context.businessID : information.businessID;
        const measurementId = context?.measurementId ? context.measurementId : information.measurementId;
        return {
            platform: DatastoreAccessInformation.resolvePlatform(information),
            accountId: information.accountId ? information.accountId : information['cloudId'],
            region: information.region ? information.region : DEFAULT_DATASTORE_REGION,
            iamRoleArn: information.iamRoleArn,
            externalId: information.externalId,
            ingestion: DatastoreAccessInformation.ingestionLocation(businessID),
            dlq: DatastoreAccessInformation.dlqLocation(businessID),
            businessID,
            measurementId,
        };
    }

    private static enrich(
        dbAccessInformation: DatastoreAccessInformation,
        details: DatastoreAccessInformation & { [x: string]: any }
    ): DatastoreAccessInformation {
        const enriched = new DatastoreAccessInformation(details);
        if (dbAccessInformation) {
            Object.assign(dbAccessInformation, enriched);
            return dbAccessInformation instanceof DatastoreAccessInformation ? dbAccessInformation : enriched;
        }
        return enriched;
    }

    private static buildRoleArn(roleName: string): string {
        return `arn:aws:iam::${process.env.AWS_ACCOUNT_ID ? process.env.AWS_ACCOUNT_ID : ''}:role/${roleName}`;
    }

    private static roleNameFromArn(iamRoleArn?: string): string | undefined {
        if (iamRoleArn && iamRoleArn.includes(':role/')) {
            const [, roleName] = iamRoleArn.split(':role/');
            return roleName ? roleName.split('/').pop() : undefined;
        }
        return undefined;
    }

    private static translateError(e, accountId: string) {
        const code = e?.name ? e.name : e?.Code;
        if (code && String(code).toLowerCase().includes('malformedpolicy')) {
            return new BadRequestException(`AccountId: ${accountId} is invalid`);
        }
        return e;
    }
}

