    /**
     * Delivers a measurement, which could not be processed, to the dead letter queue.
     *
     * The failure is written under the source key of the failed input, mirrored into the
     * dead letter queue datastore, suffixed with `.message.text`. The object holds the failed
     * input alongside the metadata of the failed processing attempt so it can be replayed.
     */
    static async publishFailureToDLQ(failure: MeasurementFailure, error?: unknown) {
        const Bucket = `${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}`;
        const sourceKey = StandardMeasurementEntity.relativeSourceKey(failure);
        const Key = `${sourceKey}${DLQ_OBJECT_SUFFIX}`;
        const failedInput = failure?.message !== undefined ? failure.message : failure?.failedInput;
        const thrown = error !== undefined ? error : failure?.error;
        const errorMessage = StandardMeasurementEntity.errorToMessage(thrown);
        const businessID = failure?.businessID ? failure.businessID : sourceKey.split('/')[0];

        const body = {
            message: failedInput,
            failedInput,
            businessID,
            s3Key: failure?.s3Key ? failure.s3Key : failure?.sourceKey ?? failure?.key,
            sourceKey,
            dlqBucket: Bucket,
            dlqKey: Key,
            error: errorMessage,
            origin: failure?.origin ? failure.origin : 'usage',
            timeStamp: new Date().toISOString(),
        };

        const s3 = new S3({
            region: process.env.AWS_REGION ? process.env.AWS_REGION : 'us-east-1',
        });
        await s3.send(
            new PutObjectCommand({
                Bucket,
                Key,
                Body: JSON.stringify(body),
                ContentType: 'text/plain',
                Metadata: {
                    businessID: StandardMeasurementEntity.metadataValue(businessID),
                    error: StandardMeasurementEntity.metadataValue(errorMessage),
                    sourceKey: StandardMeasurementEntity.metadataValue(sourceKey),
                },
            })
        );
        AuditService.publishEvent({
            data: [body],
            message: 'Published failed measurement to the DLQ',
            topic: AuditScope.ERROR,
        });
        return { message: 'Published failed measurement to the DLQ', bucket: Bucket, key: Key };
    }

    /**
     * Resolves the key of a failed input, relative to the datastore it was read from.
     * Keys which are already relative are returned untouched.
     */
    static relativeSourceKey(failure: MeasurementFailure | string): string {
        const provided =
            typeof failure === 'string' ? failure : failure?.s3Key ?? failure?.sourceKey ?? failure?.key ?? '';
        let key = `${provided}`;
        if (key.startsWith('s3://')) {
            // s3://bucket/businessID/key -> businessID/key
            key = key.replace('s3://', '').split('/').slice(1).join('/');
        }
        if (key.startsWith('arn:aws:s3:::')) {
            key = key.replace('arn:aws:s3:::', '').split('/').slice(1).join('/');
        }
        key = key.replace(/^\/+/, '');
        const sourceBucket = process.env.DB_MEASUREMENT_BUCKET_NAME;
        if (sourceBucket && key.startsWith(`${sourceBucket}/`)) {
            key = key.slice(`${sourceBucket}/`.length);
        }
        if (!key) {
            const businessID = typeof failure === 'string' ? undefined : failure?.businessID;
            key = `${businessID ? businessID : 'unknown'}/${randomUUID()}`;
        }
        return key;
    }

    private static errorToMessage(error: unknown): string {
        if (!error) {
            return 'Failed to process measurement';
        }
        if (typeof error === 'string') {
            return error;
        }
        const { message, name } = error as Error;
        if (message) {
            return name ? `${name}: ${message}` : message;
        }
        return `${error}`;
    }

    private static metadataValue(value: unknown): string {
        return `${value === undefined || value === null ? '' : value}`.replace(/[^\x20-\x7E]/g, '').slice(0, 1024);
    }
