    /**
     * Collect usage data by API-based method.
     * See <a href="https://docs.paigo.tech/measure-usage-and-collect-data/measure-and-collect-usage-data-at-production-scale">Measure and Collect Usage Data At Production Scale</a>
     * for full documentation on Paigo <b>Usage Measurement and Collection</b>.
     * @param createUsageDto
     * @param request
     */
    @ApiCreatedResponse({
        status: 201,
        description: 'OK',
        type: BasicResponseDTO,
    })
    @ApiBadRequestResponse({
        status: 400,
        description: 'Bad Request',
        type: BasicResponseDTO,
    })
    @ApiOperation({ operationId: 'Collect usage data' })
    @UseGuards(AuthGuard('jwt'))
    @Post()
    create(@Body() createUsageDto: CreateUsageDto, @Req() request: Request) {
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        //@ts-ignore
        const { businessID } = request.user;
        return this.usageService.create({ ...createUsageDto, businessID });
    }

    /**
     * Collect usage data delivered by the internal datastore connectors.
     *
     * The connector posts a single standard usage record, as a JSON string, alongside the key of the
     * object it was read from. The first segment of that key is the businessID which owns the record.
     *
     * Records which cannot be processed are delivered to the dead letter queue of the business
     * for manual processing, they are never retried by the connector.
     */
    @ApiExcludeEndpoint()
    @UseGuards(LogGaurd, AuthGuard('jwt'))
    @Post('db')
    async dbUsage(@Body() createUsageDto: DbMeasuredusageDto) {
        UsageController.logger.log('Starting DB Usage Endpoint execution');

        const { message, s3Key } = createUsageDto ? createUsageDto : ({} as DbMeasuredusageDto);
        // TODO: check if the passed in BusinessID is an authorized producer, if not throw message away
        try {
            if (!s3Key) {
                throw new Error('No s3Key was provided with the usage record');
            }
            const businessID = UsageController.businessIDFromKey(s3Key);
            if (!businessID) {
                throw new Error(`Unable to determine the businessID from the s3Key: ${s3Key}`);
            }
            const parsed = UsageController.parseUsageRecord(message);
            const input = { ...parsed, businessID };
            return await this.usageService.create(input);
        } catch (error) {
            UsageController.logger.error(
                `Failed to process usage record for s3Key: ${s3Key}, publishing to the DLQ`,
                error
            );
            return UsageController.publishToDLQ({ message, s3Key }, error);
        }
    }

    /**
     * Parses, and sanity checks, the usage record delivered by a connector.
     * Malformed records throw so they can be delivered to the dead letter queue.
     */
    private static parseUsageRecord(message: DbMeasuredusageDto['message'] | string): CreateUsageDto {
        const parsed = typeof message === 'string' ? JSON.parse(message) : message;
        if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
            throw new Error('The usage record is not a usage record object');
        }
        const { dimensionId, recordValue } = parsed as CreateUsageDto;
        if (!dimensionId || recordValue === undefined || recordValue === null) {
            throw new Error('The usage record is missing a dimensionId and or a recordValue');
        }
        return parsed as CreateUsageDto;
    }

    /**
     * The businessID owning a usage record is the first segment of the key it was read from.
     */
    private static businessIDFromKey(s3Key: string): string {
        const [businessID] = StandardMeasurementEntity.relativeSourceKey(s3Key).split('/');
        return businessID;
    }

    private static async publishToDLQ(failure: { message?: unknown; s3Key?: string }, error: unknown) {
        try {
            return await StandardMeasurementEntity.publishFailureToDLQ(
                { ...failure, origin: 'dbUsage' },
                error
            );
        } catch (dlqError) {
            UsageController.logger.error('Failed to publish the usage record to the DLQ', dlqError);
            return { message: 'Failed to publish the usage record to the DLQ' };
        }
    }
}

