private static getIamClient(region?: string) {
    const options = {
        region: process.env.AWS_REGION ? process.env.AWS_REGION : region ? region : DEFAULT_DATASTORE_REGION,
    };
    // Both the aggregated and the bare client are supported so the SDK can be swapped out freely
    const clients = [IAM, IAMClient].filter((client) => typeof client === 'function');
    let thrown;
    for (const Client of clients) {
        try {
            return new Client(options);
        } catch (e) {
            thrown = e;
        }
    }
    throw thrown ? thrown : new InternalServerErrorException('No IAM client is available');
}

/**
 * Dispatches an IAM command, commands which are not available are skipped.
 */
private static async sendCommand(iam, Command, input): Promise<any> {
    if (typeof Command !== 'function') {
        return undefined;
    }
    return iam.send(new Command(input));
}

/**
 * Provisioning failures which are caused by the input of the business, an invalid account,
 * are reported back. Every other failure is audited, the generated access information is
 * still stored so the provisioning can be retried.
 */
private static handleProvisioningError(e, { accountId, roleName }: { accountId: string; roleName: string }) {
    const code = e?.name ? e.name : e?.Code;
    if (code && String(code).toLowerCase().includes('malformedpolicy')) {
        throw new BadRequestException(`AccountId: ${accountId} is invalid`);
    }
    MeasurementConfigLogger.error(`Failed to provision access for role ${roleName}`, e);
    AuditService.publishEvent({
        data: [{ err: e, roleName, accountId }],
        message: `Failed to provision datastore access for role ${roleName}`,
        topic: AuditScope.ERROR,
    });
}

