import { CreateRoleCommand, PutRolePolicyCommand, UpdateAssumeRolePolicyCommand } from '@aws-sdk/client-iam';
import {
    DatastoreAccessInformation,
    DEFAULT_DATASTORE_REGION,
    MeasurementConfigEntity,
    SupportedDatastores,
} from './measurement-config.entity';
import { measurementMode } from '../dto/create-measurement-config.dto';

jest.mock('@aws-sdk/client-iam');

// eslint-disable-next-line @typescript-eslint/no-var-requires
const iamSdk = require('@aws-sdk/client-iam');

const businessID = 'fakeBusiness';
const measurementId = 'fake-measurement-id';
const accountId = '623673123435';

describe('DatastoreAccessInformation', () => {
    beforeEach(() => {
        process.env.DB_MEASUREMENT_BUCKET_NAME = 'paigo-usage-record-dump-bucket';
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = 'paigo-usage-record-dlq-bucket';
        process.env.AWS_REGION = 'us-east-1';
        jest.clearAllMocks();
    });

    it('defaults the platform and the region', () => {
        const configuration = new DatastoreAccessInformation({ accountId } as DatastoreAccessInformation);
        expect(configuration.platform).toEqual(SupportedDatastores.s3);
        expect(configuration.region).toEqual(DEFAULT_DATASTORE_REGION);
        expect(configuration.accountId).toEqual(accountId);
    });

    it('provisions a uniquely named role, trusting the customer account with a fresh external id', async () => {
        const configuration = await DatastoreAccessInformation.setupAccess(
            new DatastoreAccessInformation({ accountId, businessID, measurementId } as DatastoreAccessInformation)
        );

        expect(iamSdk.CreateRoleCommand).toHaveBeenCalledTimes(1);
        const [{ RoleName, AssumeRolePolicyDocument }] = (CreateRoleCommand as unknown as jest.Mock).mock.calls[0];
        expect(RoleName).toEqual(`datastore-${businessID}-${measurementId}`);

        const trustPolicy = JSON.parse(AssumeRolePolicyDocument);
        expect(trustPolicy.Statement[0].Principal.AWS).toEqual(`arn:aws:iam::${accountId}:root`);
        expect(trustPolicy.Statement[0].Condition.StringEquals['sts:ExternalId']).toEqual(configuration.externalId);
        expect(configuration.externalId).toBeTruthy();

        const [{ PolicyDocument }] = (PutRolePolicyCommand as unknown as jest.Mock).mock.calls[0];
        expect(PolicyDocument).toContain(`arn:aws:s3:::paigo-usage-record-dump-bucket/${businessID}/*`);
        expect(PolicyDocument).toContain(`arn:aws:s3:::paigo-usage-record-dlq-bucket/${businessID}/*`);

        expect(configuration.iamRoleArn).toContain(`datastore-${businessID}-${measurementId}`);
        expect(configuration.ingestion).toEqual(`s3://paigo-usage-record-dump-bucket/${businessID}`);
        expect(configuration.dlq).toEqual(`s3://paigo-usage-record-dlq-bucket/${businessID}`);
        expect(configuration.region).toEqual(DEFAULT_DATASTORE_REGION);
    });

    it('updates the trust of the role while preserving the role and the external id', async () => {
        const iamRoleArn = `arn:aws:iam::214826386939:role/datastore-${businessID}-${measurementId}`;
        const externalId = 'already-generated-external-id';
        const updatedAccountId = '999999999999';

        const configuration = await DatastoreAccessInformation.updateAccess(
            new DatastoreAccessInformation({
                accountId: updatedAccountId,
                iamRoleArn,
                externalId,
                businessID,
                measurementId,
            } as DatastoreAccessInformation)
        );

        expect(iamSdk.CreateRoleCommand).not.toHaveBeenCalled();
        const [{ RoleName, PolicyDocument }] = (UpdateAssumeRolePolicyCommand as unknown as jest.Mock).mock.calls[0];
        expect(RoleName).toEqual(`datastore-${businessID}-${measurementId}`);
        const trustPolicy = JSON.parse(PolicyDocument);
        expect(trustPolicy.Statement[0].Principal.AWS).toEqual(`arn:aws:iam::${updatedAccountId}:root`);
        expect(trustPolicy.Statement[0].Condition.StringEquals['sts:ExternalId']).toEqual(externalId);

        expect(configuration.iamRoleArn).toEqual(iamRoleArn);
        expect(configuration.externalId).toEqual(externalId);
        expect(configuration.accountId).toEqual(updatedAccountId);
    });

    it('persists and reads back the generated access information', async () => {
        const tags: Record<string, string> = {};
        const point = {
            tag: (key: string, value: string) => {
                tags[key] = value;
                return point;
            },
            stringField: () => point,
        };
        const entity = new MeasurementConfigEntity({
            measurementId,
            businessID,
            measurementMode: measurementMode.datastoreBased,
            measurementConfiguration: { accountId } as DatastoreAccessInformation,
            measurementName: 'datastore measurement',
            subject: 'fakeSubject',
        } as MeasurementConfigEntity);
        await MeasurementConfigEntity.setupAccessIfRequired(entity);
        MeasurementConfigEntity.transformer(entity, { getPoint: () => point } as never);

        expect(tags.platform).toEqual(SupportedDatastores.s3);
        expect(tags.accountId).toEqual(accountId);
        expect(tags.region).toEqual(DEFAULT_DATASTORE_REGION);
        expect(tags.ingestion).toEqual(`s3://paigo-usage-record-dump-bucket/${businessID}`);
        expect(tags.dlq).toEqual(`s3://paigo-usage-record-dlq-bucket/${businessID}`);
        expect(tags.externalId).toBeTruthy();
        expect(tags.iamRoleArn).toBeTruthy();

        const readEntity = MeasurementConfigEntity.dbModelToEntity({
            ...tags,
            _value: measurementMode.datastoreBased,
        });
        expect(readEntity.measurementConfiguration).toEqual(entity.measurementConfiguration);
    });
});

import { PutObjectCommand, S3, S3Client } from '@aws-sdk/client-s3';
import { mockClient } from 'aws-sdk-client-mock';
import { PrivateAPIUsageController } from './usage.controller';
import { UsageService } from './usage.service';

const businessID = 'fakeBusiness';
const usageRecord = {
    timeStamp: '2023-02-08T19:24:10Z',
    applicationId: 'fakeApplication',
    dimensionId: 'fakeDimension',
    recordValue: 5,
};

describe('PrivateAPIUsageController dbUsage', () => {
    const create = jest.fn();
    const controller = new PrivateAPIUsageController({ create } as unknown as UsageService);
    const s3Mock = mockClient(S3Client);

    beforeEach(() => {
        process.env.DB_MEASUREMENT_BUCKET_NAME = 'paigo-usage-record-dump-bucket';
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = 'paigo-usage-record-dlq-bucket';
        s3Mock.reset();
        create.mockReset();
        create.mockResolvedValue({ message: 'Measurement created' });
    });

    afterAll(() => {
        s3Mock.restore();
    });

    it('sends valid records through the usage service with the businessID of the s3Key', async () => {
        await controller.dbUsage({
            message: JSON.stringify(usageRecord),
            s3Key: `${businessID}/2023/02/08/usage-record.json`,
        });

        expect(create).toHaveBeenCalledTimes(1);
        expect(create).toHaveBeenCalledWith({ ...usageRecord, businessID });
        expect(s3Mock.commandCalls(PutObjectCommand)).toHaveLength(0);
    });

    it('publishes malformed records to the DLQ under the mirrored source key', async () => {
        const s3Key = `${businessID}/2023/02/08/usage-record.json`;
        await controller.dbUsage({ message: 'I am not a usage record', s3Key });

        expect(create).not.toHaveBeenCalled();
        const [putObject] = s3Mock.commandCalls(PutObjectCommand);
        expect(putObject.args[0].input.Bucket).toEqual('paigo-usage-record-dlq-bucket');
        expect(putObject.args[0].input.Key).toEqual(`${s3Key}.message.text`);

        const published = JSON.parse(`${putObject.args[0].input.Body}`);
        expect(published.message).toEqual('I am not a usage record');
        expect(published.businessID).toEqual(businessID);
        expect(published.error).toBeTruthy();
        expect(published.timeStamp).toBeTruthy();
    });

    it('publishes records read from a fully qualified source key to the mirrored, relative, DLQ key', async () => {
        await controller.dbUsage({
            message: '{ not json',
            s3Key: `s3://paigo-usage-record-dump-bucket/${businessID}/2023/usage-record.json`,
        });

        const [putObject] = s3Mock.commandCalls(PutObjectCommand);
        expect(putObject.args[0].input.Key).toEqual(`${businessID}/2023/usage-record.json.message.text`);
        expect(create).not.toHaveBeenCalled();
    });

    it('publishes records which the usage service rejects to the DLQ', async () => {
        create.mockRejectedValue(new Error('Dimension does not exist'));

        await controller.dbUsage({
            message: JSON.stringify(usageRecord),
            s3Key: `${businessID}/2023/usage-record.json`,
        });

        const [putObject] = s3Mock.commandCalls(PutObjectCommand);
        expect(JSON.parse(`${putObject.args[0].input.Body}`).error).toContain('Dimension does not exist');
    });

    it('publishes to the DLQ with the aggregated client mocked', async () => {
        const aggregated = mockClient(S3);
        await controller.dbUsage({ message: 'not a record', s3Key: `${businessID}/aggregated.json` });
        expect(aggregated.commandCalls(PutObjectCommand)).toHaveLength(1);
        aggregated.restore();
    });
});

