import { PutObjectCommand, S3Client } from '@aws-sdk/client-s3';
import { mockClient } from 'aws-sdk-client-mock';
import { DLQ_OBJECT_SUFFIX, StandardMeasurementEntity } from './standardMeasurement.entity';

describe('StandardMeasurementEntity DLQ delivery', () => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const s3Mock = mockClient(S3Client as any);

    beforeEach(() => {
        process.env.DB_MEASUREMENT_BUCKET_NAME = 'paigo-usage-record-dump-bucket';
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = 'paigo-usage-record-dlq-bucket';
        s3Mock.reset();
    });

    afterAll(() => {
        s3Mock.restore();
    });

    it('mirrors an already relative source key into the DLQ', async () => {
        const response = await StandardMeasurementEntity.publishFailureToDLQ(
            { message: 'I am not a usage record', s3Key: 'fakeBusiness/2023/usage-record.json' },
            new Error('Unexpected token I in JSON at position 0')
        );

        expect(response.bucket).toEqual('paigo-usage-record-dlq-bucket');
        expect(response.key).toEqual(`fakeBusiness/2023/usage-record.json${DLQ_OBJECT_SUFFIX}`);

        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const [putObject] = s3Mock.commandCalls(PutObjectCommand as any);
        expect(putObject.args[0].input).toEqual(
            expect.objectContaining({
                Bucket: 'paigo-usage-record-dlq-bucket',
                Key: `fakeBusiness/2023/usage-record.json${DLQ_OBJECT_SUFFIX}`,
            })
        );
        const published = JSON.parse(`${putObject.args[0].input['Body']}`);
        expect(published.message).toEqual('I am not a usage record');
        expect(published.businessID).toEqual('fakeBusiness');
        expect(published.error).toContain('Unexpected token I in JSON at position 0');
    });

    it('mirrors a fully qualified source key into the DLQ', async () => {
        const response = await StandardMeasurementEntity.publishFailureToDLQ({
            message: 'I am not a usage record',
            s3Key: 's3://paigo-usage-record-dump-bucket/fakeBusiness/2023/usage-record.json',
            error: 'malformed record',
        });

        expect(response.key).toEqual(`fakeBusiness/2023/usage-record.json${DLQ_OBJECT_SUFFIX}`);
    });
});

